// Keep files generated by project tools on the project drive, including temp files.
import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
export const PROJECT_ROOT=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');
const temporary=path.join(PROJECT_ROOT,'.tmp');
const cache=path.join(PROJECT_ROOT,'.cache');
fs.mkdirSync(temporary,{recursive:true});
fs.mkdirSync(cache,{recursive:true});
Object.assign(process.env,{
  TMP:temporary,TEMP:temporary,TMPDIR:temporary,
  npm_config_cache:path.join(cache,'npm'),
  PIP_CACHE_DIR:path.join(cache,'pip'),
  HF_HOME:path.join(cache,'huggingface'),
  HF_HUB_CACHE:path.join(cache,'huggingface','hub'),
  XDG_CACHE_HOME:cache,
  PYTHONDONTWRITEBYTECODE:'1'
});
